#include <iostream>

// Computes square; stack frame contains parameter x and return address back to main
int square(int x) {
    return x * x;
}

int main() {
    // a is an automatic local variable stored inside main's stack frame
    int a = 10;
    std::cout << a << " squared: " << square(a) << "\n";
    return 0;
}

#include <iostream>

// Function with empty parameter list
void printBanner() {
    std::cout << "=== Cube Calculator ===\n";
}

// Inline function: advises compiler to replace call with expression
// const enforces the principle of least privilege
inline double cube(const double side) {
    return side * side * side;
}

int main() {
    printBanner();
    constexpr double side = 3.5;
    std::cout << "Volume of cube with side " << side << " is " << cube(side) << "\n";
    return 0;
}
